import * as React from "react";
import {SvgMpaIcon} from "../../assets/icons/index";
import { Tooltip } from "../tooltip";

export interface IconComponentProps {    
    /**
     * determines the name of Icon
     */
    iconName: keyof typeof SvgMpaIcon | string;
      /**
     * determines the colour of Icon
     */
    colour?: string;
    /**
     * determines the size of Icon
     */
    size?: string | number;

    /**
    * Text to be displayed inside the tooltip.
    */
    tooltipText?: string;
    /**
     * The placement of the overlay in relation to the icon.
     */
    tooltipPlacement?: "right" | "left" | "top" | "bottom";
}

export const MpaIcon: React.FC<IconComponentProps> = ({iconName, size, colour,tooltipText,tooltipPlacement}) => {
    
    // const IconComponent = SvgMpaIcon[iconName];  
    const IconComponent = (SvgMpaIcon as Record<string, any>)[iconName];

    if (!IconComponent) {
        console.warn(`MpaIcon: icon "${iconName}" not found in SvgMpaIcon`);
        return null;
    }
    return (
        <>
        {tooltipText && tooltipText.trim().length > 0 ? (
        <Tooltip tooltipText={tooltipText} tooltipPlacement={tooltipPlacement}>
            <IconComponent size={size} color={colour}/>
        </Tooltip> 
         ):(<IconComponent size={size} color={colour}/>)
        }
        </> 
    )
}

export default MpaIcon;